import{_ as a,o as e,c as r,a2 as i}from"./chunks/framework.CHeM0PsO.js";const o="/images/agent-create-basic.webp",l="/images/agent-create-persona.webp",d="/images/agent-create-dialogue.webp",n="/images/agent-create-rules.webp",_=JSON.parse('{"title":"创作角色","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/create.md","filePath":"guide/agent/create.md","lastUpdated":1793029602000}'),s={name:"guide/agent/create.md"};function h(g,t,c,p,u,b){return e(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="创作角色" tabindex="-1">创作角色 <a class="header-anchor" href="#创作角色" aria-label="Permalink to &quot;创作角色&quot;">​</a></h1><p>进入「智能体 → 创作 → 角色设定」，点击「新建角色」创建自己的角色。角色编辑页按以下几个部分组织。</p><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><p><img src="'+o+'" alt="基本信息"></p><ul><li><strong>名称</strong>：角色的名字。</li><li><strong>简介</strong>：展示在广场卡片和列表上，不会发送给模型。</li><li><strong>头像</strong>：角色的形象图片。</li><li><strong>默认生图参考图</strong>：最多 5 张，每张不超过 5MiB。仅在会话选择了支持参考图的<a href="/guide/agent/chat#生图">生图</a>模型时发送，用于稳定插图里的角色形象。</li><li><strong>允许公开角色提示词</strong>：开启后，广场详情页会显示完整提示词供其他用户参考，默认关闭。</li></ul><h2 id="人设" tabindex="-1">人设 <a class="header-anchor" href="#人设" aria-label="Permalink to &quot;人设&quot;">​</a></h2><p><img src="'+l+'" alt="人设"></p><p>人设是模型每轮都会读到的内容。</p><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>性格与行为</td><td>角色的性格特点、行为方式</td></tr><tr><td>背景设定</td><td>角色的经历、身份与世界观</td></tr><tr><td>说话方式</td><td>语气、称呼、口癖等表达习惯</td></tr><tr><td>禁止行为</td><td>角色不会做的事，用于约束模型输出（安全边界）</td></tr></tbody></table><h2 id="对话与示例" tabindex="-1">对话与示例 <a class="header-anchor" href="#对话与示例" aria-label="Permalink to &quot;对话与示例&quot;">​</a></h2><p><img src="'+d+'" alt="对话与示例"></p><ul><li><strong>开场白</strong>：创建会话时作为角色的第一条消息自动插入，留空则不插入。</li><li><strong>示例对话</strong>：逐条选择说话方（用户 / 助手）并填写内容，最多 24 条。保存后作为参考示例进入系统提示，模型只用它参考语气，不当作真实聊天记录。</li></ul><h2 id="世界书" tabindex="-1">世界书 <a class="header-anchor" href="#世界书" aria-label="Permalink to &quot;世界书&quot;">​</a></h2><p>角色的背景知识库，按关键词、手动或常驻方式注入，详见<a href="/guide/agent/worldbook">世界书</a>。</p><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h2><p><img src="'+n+'" alt="规则"></p><p>为角色定义行为规则，最多 5 条。每条规则包含名称、简介（50 字以内，向用户说明作用）和规则内容。</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>常驻规则</td><td>始终生效，用户无法关闭</td></tr><tr><td>可切换规则</td><td>用户可在会话的「规则」标签页开关；可另填「关闭状态提示词」，关闭时注入，留空则关闭时不注入</td></tr></tbody></table><p>可切换规则可以设置是否默认开启。用户在会话中只能看到规则的名称和简介，看不到规则内容。</p><h2 id="正则与表情包" tabindex="-1">正则与表情包 <a class="header-anchor" href="#正则与表情包" aria-label="Permalink to &quot;正则与表情包&quot;">​</a></h2><ul><li><strong>正则</strong>：对用户消息或 AI 输出做过滤，详见<a href="/guide/agent/regex-stickers#正则">正则与表情包</a>。</li><li><strong>表情包</strong>：角色专属贴纸，详见<a href="/guide/agent/regex-stickers#角色表情包">正则与表情包</a>。</li></ul><h2 id="版本管理" tabindex="-1">版本管理 <a class="header-anchor" href="#版本管理" aria-label="Permalink to &quot;版本管理&quot;">​</a></h2><p>角色和对话风格都支持版本管理：查看草稿与发布版的差异、历史版本、回滚到之前的版本。</p><h2 id="测试与发布" tabindex="-1">测试与发布 <a class="header-anchor" href="#测试与发布" aria-label="Permalink to &quot;测试与发布&quot;">​</a></h2><ol><li>新建的角色是<strong>草稿</strong>，可以在创作列表点「开始聊天」测试，测试会话只有自己可见。</li><li>点击「提交审核」。</li><li>审核通过后发布到广场，其他用户即可使用。广场显示的是已发布版本，草稿里的后续改动要再次发布才会生效。</li></ol><p>审核未通过时，作品上会显示外审反馈的分类和原因，修改后可重新提交。对话风格也走同样的流程，见<a href="/guide/agent/styles">对话风格</a>。</p><p>平台对模型的每次输出都有内容审查，违规内容会被拦截。</p>',27)])])}const f=a(s,[["render",h]]);export{_ as __pageData,f as default};
